declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';$error=null;$p=null;try{$pdo=ps23_db();ps23_ensure($pdo);$ctx=ps23_context($pdo);$p=ps23_product($pdo,$ctx['organization_id'],(int)($_GET['id']??0));}catch(Throwable $e){$error=$e->getMessage();}function pd_av(string $s):string{return match($s){'available'=>'Available','limited'=>'Limited availability','unavailable'=>'Currently unavailable',default=>'Availability confirmed at review'};}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=ps23_h($p['product_name']??'Product')?> - Healthcare Wellness Club</title><link rel="stylesheet" href="store.css"></head><body><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Product Detail</small></span></a><div class="store-actions"><a class="store-btn" href="index.php">Products</a><a class="store-btn primary" href="cart.php">Cart (<span data-cart-count>0</span>)</a></div></div></header><main class="store-shell"><?php if($error):?><div class="notice bad"><?=ps23_h($error)?></div><?php else:?><section class="two-col"><article class="card"><div class="product-image" style="border-radius:16px;max-height:520px"><?php if(!empty($p['verified_image'])):?><img src="<?=ps23_h($p['verified_image'])?>" alt="<?=ps23_h($p['product_name'])?>"><?php else:?><div class="product-placeholder" style="width:130px;height:130px">HWC</div><?php endif;?></div></article><aside class="card"><div class="store-kicker"><?=ps23_h($p['category_name'])?></div><h1><?=ps23_h($p['product_name'])?></h1><p class="meta">Stock No. <?=ps23_h($p['sku'])?><?=!empty($p['pack_size'])?' • '.ps23_h($p['pack_size'].' '.$p['pack_unit']):''?></p><span class="pill <?=ps23_h($p['availability_status'])?>"><?=ps23_h(pd_av($p['availability_status']))?></span><div style="margin:18px 0"><div class="price"><?=ps23_money($p['mrp'])?></div><div class="vp"><?=ps23_h(rtrim(rtrim(number_format((float)$p['volume_points'],3,'.',''),'0'),'.'))?> VP</div><div class="meta">Source-listed MRP • effective <?=ps23_h($p['effective_from'])?></div></div><div class="notice">This public page does not assign Preferred or Associate eligibility. Final payable amount, taxes and availability are confirmed by the club before payment.</div><button class="store-btn primary" style="width:100%" data-add-product="<?=$p['id']?>" <?=$p['availability_status']==='unavailable'?'disabled':''?>>Add to Cart</button></aside></section><?php endif;?></main><footer class="store-footer">Healthcare Wellness Club • Public Product Portal</footer><script src="store.js"></script></body></html>